volume.script:
volume = vbuy + vsell
delta = vbuy - vsell

getStDevAboveAvg = function(v) {
  a = sma(Math.pow(v,2),options.length)
  b = Math.pow(sum(v,options.length),2)/Math.pow(options.length,2)
  stdev = Math.sqrt(a - b)
  avg = sma(v, options.length)
  return avg+stdev*options.mult
}

vThreshold = getStDevAboveAvg(volume)
absDelta = Math.abs(delta)
deltaThreshold = getStDevAboveAvg(absDelta)

volumeColor = vbuy > vsell ? options.upColor : options.downColor
if (volume > vThreshold)
  volumeColor = vbuy > vsell ? options.upBgColor : options.downBgColor

plothistogram({
  time: time,
  value: volume,
  color: volumeColor
})

if (options.showDelta && absDelta > deltaThreshold) {
  plothistogram({ time: time, value: absDelta, color: options.deltaColor})
}

cb-premium.script:
// Coinbase premium (COINBASE:BTC-USD vs BINANCE:btcusdt) in bps.
// The LEVEL carries a structural ~5-10 bps offset from USDT trading off par, so the raw value is
// usually negative. The SIGNAL is the deviation from its own rolling mean (histogram):
//   Green ABOVE zero  = US bid strengthening vs its recent norm
//   Orange BELOW zero = US bid weakening vs its recent norm
// Raw bps level is split into two lines so its SIGN is visible at a glance:
//   BLUE line above zero   = Coinbase trading OVER Binance (Coinbase blue; rare, real US bid)
//   YELLOW line below zero = Binance over Coinbase (Binance yellow; the normal state)
// aggr cannot recolour a single line per bar, so the inactive half sits flat on the zero line.
cbPx = COINBASE:BTC-USD.close
bnPx = BINANCE:btcusdt.close
cbBps = (cbPx / bnPx - 1) * 10000
baseline = sma(cbBps, options.baseline)
dev = cbBps - baseline
rawPos = Math.max(cbBps, 0)
rawNeg = Math.min(cbBps, 0)
plotline(0, color=options.zeroColor)
plothistogram({ time: time, value: dev, color: dev > 0 ? options.posColor : options.negColor }, title="CB Prem vs 24h avg")
line(rawPos, color=options.rawPosColor, lineWidth=2, title="CB Prem +bps")
line(rawNeg, color=options.rawColor, title="CB Prem -bps")

spot-perp-flow.script:
// Aggression spread: who is hitting the tape harder on the buy side, spot or perps?
// Each side's delta is divided by its own volume -> a ratio in [-1, +1] per bar
//   (+1 = every trade was a market buy, -1 = every trade was a market sell).
// The bar plotted is  spot_ratio - perp_ratio, smoothed.
//   Blue ABOVE zero  = spot more aggressively bought than perps  (spot-led; tends to hold)
//   Pink BELOW zero  = perps more aggressively bought than spot  (perp-led; tends to round-trip)
sb = source(vbuy, type=spot)
ss = source(vsell, type=spot)
pb = source(vbuy, type=perp)
ps = source(vsell, type=perp)
spotRatio = (sb - ss) / Math.max(sb + ss, 1)
perpRatio = (pb - ps) / Math.max(pb + ps, 1)
spread = sma(spotRatio - perpRatio, options.smooth)
plotline(0, color=options.zeroColor)
plothistogram({ time: time, value: spread, color: spread > 0 ? options.spotLedColor : options.perpLedColor }, title="Spot-Perp Aggression")

