venue-z-BINANCE.script:
// BINANCE ACTIVITY, z-scored against this venue's own recent history.
// Net market flow on BINANCE (all its markets in this pane), smoothed, then expressed in standard deviations of
// its own last 24h. +2 = this venue is buying two sigma harder than its normal, regardless of how big it is
// in dollars — so venues are directly comparable on one axis. Bands are drawn by the 'Venue z bands' indicator.
_vbuy=(BINANCE:btcusdt.vbuy+BINANCE:btctusd.vbuy+BINANCE:btcusdc.vbuy+BINANCE:btcfdusd.vbuy)
_vsell=(BINANCE:btcusdt.vsell+BINANCE:btctusd.vsell+BINANCE:btcusdc.vsell+BINANCE:btcfdusd.vsell)
netFlow = _vbuy - _vsell
netS = sma(netFlow, options.smooth)
netMean = sma(netS, options.zwin)
netSq = sma(netS * netS, options.zwin)
netSd = Math.sqrt(Math.max(netSq - netMean * netMean, 0))
netZ = netSd > 0 ? (netS - netMean) / netSd : 0
line(netZ, color=options.color, title="BINANCE")

